actions.script:
if (ec.web == null) { baseUrl = ''; return }
String scheme = ec.web.request.getHeader('X-Forwarded-Proto') ?: ec.web.request.getScheme()
baseUrl = scheme + '://' + ec.web.getHostName(true)

def yaml = { Object value -> '"' + (value ?: '').toString()
        .replace('\\', '\\\\').replace('"', '\\"').replace('\n', ' ') + '"' }
// first real sentence of the page, used when the page has no description front matter
def deriveDescription = { String text ->
    String paragraph = text.readLines().find({
        it.trim() && !it.startsWith('#') && !it.startsWith('---') && !it.startsWith('|') })
    if (!paragraph) return null
    paragraph = paragraph.replaceAll(/!?\[([^\]]*)\]\([^)]*\)/, '$1')
            .replaceAll(/[*`\\]/, '').trim()
    if (paragraph.length() <= 155) return paragraph
    int cut = paragraph.substring(0, 155).lastIndexOf(' ')
    return paragraph.substring(0, cut > 0 ? cut : 155) + '...'
}
// rendered markdown is cached per published version, so an edit in the admin app
// (which bumps publishedVersionName) shows up on the next request
String cacheKey = "${productStoreId}|${page.sitePath}|${pageOut.publishedVersionName}".toString()
def pageCache = ec.cache.getCache('growerp.seo.page')
String body = (String) pageCache.get(cacheKey)
if (body == null) {
    String location = pageOut.pageLocation
    String rendered = null
    // md pages are markdown already: the .md.ftl renderer would turn them into html
    if (page.pageType == 'ftl') try {
        StringWriter sw = new StringWriter()
        ec.resource.getTemplateRendererByLocation(location).render(location, sw)
        rendered = sw.toString()
        // the freemarker exception handler writes errors inline instead of throwing
        if (rendered.contains('[Template Error')) rendered = null
    } catch (Exception e) {
        ec.logger.warn("get#PageMarkdown could not render ${location}: ${e.message}")
    }
    if (rendered == null) {
        // md content, or a page that would not render: strip the freemarker constructs
        rendered = ((String) pageOut.pageText).replaceAll(/(?s)<#--.*?-->/, '')
                .replaceAll(/(?s)<#[^>]*>/, '').replaceAll(/\$\{[^}]*\}/, '')
    }
    if (page.pageType == 'ftl') {
        try {
            def htmlToMarkdown = ec.resource.script(
                    "component://PopRestStore/service/popstore/HtmlToMarkdown.groovy", null)
            body = htmlToMarkdown.convert(rendered, baseUrl)
        } catch (Exception e) {
            ec.logger.warn("get#PageMarkdown could not convert ${location}: ${e.message}")
            body = org.jsoup.Jsoup.parseBodyFragment(rendered).text()
        }
    } else {
        // md content: the page text already is markdown, only drop the seo comments
        body = rendered.replaceAll(/(?s)<!--.*?-->/, '').replaceAll(/\n{3,}/, '\n\n').trim() + '\n'
    }
    pageCache.put(cacheKey, body)
}
if (!body?.trim()) { markdown = null; return }

String description = page.description ?: deriveDescription(body)
String updated = pageOut.pageReference?.getLastModified() ?
        new java.text.SimpleDateFormat('yyyy-MM-dd').format(
                new Date(pageOut.pageReference.getLastModified())) : null
StringBuilder md = new StringBuilder()
md.append('---\n')
md.append('title: ').append(yaml(page.title ?: productStore.storeName)).append('\n')
if (description) md.append('description: ').append(yaml(description)).append('\n')
md.append('canonical: ').append(yaml(page.url)).append('\n')
if (updated) md.append('updated: ').append(yaml(updated)).append('\n')
md.append('site: ').append(yaml(productStore.storeName)).append('\n')
md.append('---\n\n')
if (page.title && !body.trim().startsWith('# ')) md.append('# ').append(page.title).append('\n\n')
md.append(body)
markdown = md.toString()

def dateFormat = new java.text.SimpleDateFormat('yyyy-MM-dd')
StringBuilder out = new StringBuilder()
out.append('<?xml version="1.0" encoding="UTF-8"?>\n')
out.append('<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n')
for (Object pageObj in sitePagesOut.pages) {
    Map page = (Map) pageObj
    out.append('  <url><loc>').append(page.url.replace('&', '&amp;')).append('</loc>')
    if (page.lastModified) out.append('<lastmod>')
            .append(dateFormat.format(new Date(page.lastModified as Long))).append('</lastmod>')
    out.append('</url>\n')
}
Set otherPaths = new LinkedHashSet()
for (Object categoryObj in (storeInfo.categoryList ?: [])) {
    otherPaths.add('/category/' + ((Map) categoryObj).productCategoryId)
}
otherPaths.addAll(productUrls)
int count = 0
for (String path in otherPaths) {
    if (++count > 5000) break
    out.append('  <url><loc>').append(baseUrl).append(path).append('</loc></url>\n')
}
out.append('</urlset>\n')
text = out.toString()
